CREATE TABLE public.notification_settings (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, push_enabled boolean DEFAULT false NOT NULL, permission_granted_at timestamp with time zone, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.notification_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notification_settings ADD CONSTRAINT notification_settings_pkey PRIMARY KEY (id);
ALTER TABLE public.notification_settings ADD CONSTRAINT notification_settings_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
ALTER TABLE public.notification_settings ADD CONSTRAINT notification_settings_user_id_key UNIQUE (user_id);
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.notification_settings TO anon;
GRANT ALL ON public.notification_settings TO authenticated;
GRANT ALL ON public.notification_settings TO service_role;
CREATE TRIGGER notification_settings_set_updated_at BEFORE UPDATE ON public.notification_settings FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE POLICY "Notification settings are deletable by owner" ON public.notification_settings FOR DELETE TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "Notification settings are insertable by owner" ON public.notification_settings FOR INSERT TO authenticated WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "Notification settings are updatable by owner" ON public.notification_settings FOR UPDATE TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "Notification settings are viewable by owner" ON public.notification_settings FOR SELECT TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id));
CREATE TABLE public.reminders (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, time_of_day time without time zone NOT NULL, is_enabled boolean DEFAULT true NOT NULL, repeat text DEFAULT 'daily'::text NOT NULL, label text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.reminders ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reminders ADD CONSTRAINT reminders_pkey PRIMARY KEY (id);
ALTER TABLE public.reminders ADD CONSTRAINT reminders_repeat_check CHECK (repeat = ANY (ARRAY['daily'::text, 'weekly'::text]));
ALTER TABLE public.reminders ADD CONSTRAINT reminders_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.reminders TO anon;
GRANT ALL ON public.reminders TO authenticated;
GRANT ALL ON public.reminders TO service_role;
CREATE INDEX reminders_user_time_idx ON public.reminders (user_id, time_of_day);
CREATE TRIGGER reminders_set_updated_at BEFORE UPDATE ON public.reminders FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE POLICY "Reminders are deletable by owner" ON public.reminders FOR DELETE TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "Reminders are insertable by owner" ON public.reminders FOR INSERT TO authenticated WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "Reminders are updatable by owner" ON public.reminders FOR UPDATE TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "Reminders are viewable by owner" ON public.reminders FOR SELECT TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id));
